def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_defects = sum(1 for a, b in history if b == 'D')

    if opp_defects > n * 0.5:
        return 'D'

    last_opp = history[-1][1]
    last_my = history[-1][0]

    if last_opp == 'D':
        return 'D'

    if last_my == 'D':
        return 'C'

    if opp_defects == 0 and n > 50:
        if n % 10 == 0:
            return 'D'

    return 'C'
